column-group-key-filter.specification:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID]
input: {SRC: {path: input.csv, types: {V: int}}}
output: {path: result.csv, columns: [ID, VALUE]}
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: VALUE, type: str, derivation: {case: [{when: 'TRUE', then: {source: {variable: SRC.ID, filter: 'SRC.V > 0'}}}, {otherwise: "'unused'"}]}}
rows:
  - {id: grouped, dataset: SRC, group_by: [SRC.ID]}

